  1	import { DateTime, Effect, Option, Predicate, Stream } from "effect";
  2	import { defineOperation } from "./define-operation.js";
  3	import type {
  4		HevyExecutionOptions,
  5		HevyOperationSafety,
  6	} from "@hevy-mcp/hevy-client";
  7	import type { HevyRequestEffectError } from "@hevy-mcp/hevy-client/internal";
  8	import type { BodyMeasurement, Workout } from "@hevy-mcp/hevy-client/types";
  9	import {
 10		PaginationMismatchError,
 11		TrainingSummaryDataError,
 12		TrainingSummaryValidationError,
 13		hasNextPage,
 14		isExpectedReadEndOfList,
 15	} from "./operation-errors.js";
 16	import type {
 17		BodyMeasurementsListOperation,
 18		BodyMeasurementsListOutput,
 19	} from "./body-measurements.js";
 20	import type { WorkoutsListOperation, WorkoutsListOutput } from "./workouts.js";
 21	
 22	const TRAINING_SUMMARY_PAGE_SIZE = 10;
 23	const MAX_TRAINING_SUMMARY_WEEKS = 12;
 24	const MIN_TRAINING_SUMMARY_WEEKS = 1;
 25	const SCAN_CONCURRENCY = 2;
 26	
 27	export interface TrainingSummaryInput {
 28		readonly weeks: number;
 29	}
 30	
 31	export interface TrainingSummaryOperationOptions {
 32		readonly maxWeeks?: number;
 33		readonly strictPagination?: boolean;
 34	}
 35	
 36	export interface TrainingSummaryPeriod {
 37		readonly start_date: string;
 38		readonly end_date: string;
 39		readonly weeks: number;
 40	}
 41	
 42	export interface TrainingSummarySession {
 43		readonly id?: string;
 44		readonly title?: string;
 45		readonly start_time?: string;
 46		readonly end_time?: string;
 47		readonly duration_seconds?: number;
 48		readonly exercise_count: number;
 49		readonly set_count: number;
 50	}
 51	
 52	export interface TrainingSummaryMeasurement {
 53		readonly date: string;
 54		readonly weight_kg?: number;
 55		readonly lean_mass_kg?: number;
 56		readonly fat_percent?: number;
 57	}
 58	
 59	type MutableTrainingSummarySession = {
 60		id?: string;
 61		title?: string;
 62		start_time?: string;
 63		end_time?: string;
 64		duration_seconds?: number;
 65		exercise_count: number;
 66		set_count: number;
 67	};
 68	
 69	type MutableTrainingSummaryMeasurement = {
 70		date: string;
 71		weight_kg?: number;
 72		lean_mass_kg?: number;
 73		fat_percent?: number;
 74	};
 75	
 76	type MutableTrainingSummaryBodyMeasurements = {
 77		count: number;
 78		latest?: TrainingSummaryMeasurement;
 79		earliest?: TrainingSummaryMeasurement;
 80		weight_change_kg?: number;
 81	};
 82	
 83	export interface TrainingSummaryResult {
 84		readonly period: TrainingSummaryPeriod;
 85		readonly workouts: {
 86			readonly count: number;
 87			readonly total_duration_seconds: number;
 88			readonly exercise_count: number;
 89			readonly set_count: number;
 90			readonly total_volume_kg?: number;
 91			readonly unique_exercise_template_ids: string[];
 92			readonly sessions: TrainingSummarySession[];
 93		};
 94		readonly body_measurements: {
 95			readonly count: number;
 96			readonly latest?: TrainingSummaryMeasurement;
 97			readonly earliest?: TrainingSummaryMeasurement;
 98			readonly weight_change_kg?: number;
 99		};
100		readonly workflow: {
101			readonly name: "training-summary";
102			readonly pagination: {
103				readonly workouts: number;
104				readonly body_measurements: number;
105			};
106			readonly cacheStatus: "not-used";
107			readonly itemsScanned: number;
108		};
109	}
110	
111	export type WorkflowsTrainingSummaryOperations =
112		| {
113				readonly workouts: WorkoutsListOperation;
114				readonly bodyMeasurements: BodyMeasurementsListOperation;
115		  }
116		| {
117				readonly workouts: {
118					readonly list: WorkoutsListOperation;
119				};
120				readonly bodyMeasurements: {
121					readonly list: BodyMeasurementsListOperation;
122				};
123		  };
124	
125	export interface WorkflowsTrainingSummaryDescriptor {
126		readonly id: "workflows.trainingSummary";
127		readonly safety: Extract<HevyOperationSafety, "read">;
128	}
129	
130	export const workflowsTrainingSummaryDescriptor: WorkflowsTrainingSummaryDescriptor =
131		{
132			id: "workflows.trainingSummary",
133			safety: "read",
134		};
135	
136	export interface WorkflowsTrainingSummaryOperation {
137		readonly descriptor: WorkflowsTrainingSummaryDescriptor;
138		readonly effect: (
139			input: TrainingSummaryInput,
140			options?: HevyExecutionOptions,
141		) => Effect.Effect<
142			TrainingSummaryResult,
143			| HevyRequestEffectError
144			| PaginationMismatchError
145			| TrainingSummaryDataError
146			| TrainingSummaryValidationError
147		>;
148		execute(
149			input: TrainingSummaryInput,
150			options?: HevyExecutionOptions,
151		): Promise<TrainingSummaryResult>;
152	}
153	
154	export type TrainingSummaryOperation = WorkflowsTrainingSummaryOperation;
155	export type TrainingSummaryOperations = WorkflowsTrainingSummaryOperations;
156	export type TrainingSummaryAdapter = WorkflowsTrainingSummaryOperations;
157	
158	export interface TrainingSummaryPage<T> {
159		readonly items: readonly T[];
160		readonly pageCount?: number;
161		readonly endOfList?: boolean;
162	}
163	
164	export interface TrainingSummaryScanResult<T> {
165		readonly items: T[];
166		readonly pages: number;
167		readonly itemsScanned: number;
168	}
169	
170	export type TrainingSummaryPageLoader<T> = (
171		page: number,
172		pageSize: number,
173		options?: HevyExecutionOptions,
174	) => Effect.Effect<
175		TrainingSummaryPage<T>,
176		HevyRequestEffectError | PaginationMismatchError
177	>;
178	
179	function parseUtcDate(value: string | undefined): DateTime.Utc | undefined {
180		if (value === undefined) return undefined;
181		const parsed = DateTime.make(value);
182		return Option.isSome(parsed) ? parsed.value : undefined;
183	}
184	
185	function hasInvalidPageCount(
186		pageCount: number | undefined,
187		page: number,
188		hasItems: boolean,
189	): boolean {
190		return (
191			!Predicate.isNumber(pageCount) ||
192			!Number.isSafeInteger(pageCount) ||
193			pageCount < 0 ||
194			(pageCount === 0 && (page > 1 || hasItems)) ||
195			(pageCount > 0 && pageCount < page)
196		);
197	}
198	
199	/**
200	 * Collect pages while retaining only items in the requested UTC window.
201	 *
202	 * A collection's later-page 404 is represented by the list operation as an
203	 * end-of-list marker. It terminates the stream without counting a page that
204	 * did not return data.
205	 */
206	export const scanPagesInWindow = Effect.fn(
207		"operations.workflows.scanPagesInWindow",
208	)(function* <T>(
209		loader: TrainingSummaryPageLoader<T>,
210		pageSize: number,
211		startDate: string,
212		endDate: string,
213		getDate: (item: T) => string | undefined,
214		options?: HevyExecutionOptions,
215		strictPagination = false,
216	): Effect.fn.Return<
217		TrainingSummaryScanResult<T>,
218		HevyRequestEffectError | PaginationMismatchError | TrainingSummaryDataError
219	> {
220		const start = parseUtcDate(startDate);
221		const end = parseUtcDate(endDate);
222		if (start === undefined || end === undefined) {
223			return yield* new TrainingSummaryDataError({
224				collection: "training-summary",
225				message: "The training summary window contains an invalid date",
226			});
227		}
228	
229		const startMillis = DateTime.toEpochMillis(start);
230		const endExclusiveMillis = DateTime.toEpochMillis(
231			DateTime.add(end, { days: 1 }),
232		);
233		const pageStream = Stream.paginate<
234			{ readonly page: number },
235			TrainingSummaryPage<T>,
236			HevyRequestEffectError | PaginationMismatchError
237		>({ page: 1 }, (cursor) => {
238			const request = loader(cursor.page, pageSize, options);
239			return request.pipe(
240				Effect.flatMap(
241					(
242						pageResult,
243					): Effect.Effect<
244						readonly [
245							ReadonlyArray<TrainingSummaryPage<T>>,
246							Option.Option<{ readonly page: number }>,
247						],
248						HevyRequestEffectError | PaginationMismatchError
249					> => {
250						if (pageResult.endOfList === true) {
251							return Effect.succeed([
252								[] as ReadonlyArray<TrainingSummaryPage<T>>,
253								Option.none<{ readonly page: number }>(),
254							] as const);
255						}
256	
257						if (
258							strictPagination &&
259							hasInvalidPageCount(
260								pageResult.pageCount,
261								cursor.page,
262								pageResult.items.length > 0,
263							)
264						) {
265							return Effect.fail(
266								new PaginationMismatchError({
267									requested: cursor.page,
268									received: Predicate.isNumber(pageResult.pageCount)
269										? pageResult.pageCount
270										: -1,
271									collection: "training-summary",
272									message: "The API returned invalid pagination metadata",
273								}),
274							);
275						}
276						const nextPage = hasNextPage(
277							pageResult.pageCount,
278							cursor.page,
279							pageResult.items.length,
280						)
281							? Option.some({ page: cursor.page + 1 })
282							: Option.none<{ readonly page: number }>();
283						return Effect.succeed([
284							[pageResult] as ReadonlyArray<TrainingSummaryPage<T>>,
285							nextPage,
286						] as const);
287					},
288				),
289			);
290		});
291		const pages = yield* Stream.runCollect(pageStream);
292		const items: T[] = [];
293		let itemsScanned = 0;
294		for (const page of pages) {
295			itemsScanned += page.items.length;
296			for (const item of page.items) {
297				const date = parseUtcDate(getDate(item));
298				if (date === undefined) {
299					return yield* new TrainingSummaryDataError({
300						collection: "training-summary",
301						message: "The API returned an item with an invalid date",
302					});
303				}
304				const timestamp = DateTime.toEpochMillis(date);
305				if (timestamp >= startMillis && timestamp < endExclusiveMillis) {
306					items.push(item);
307				}
308			}
309		}
310		return {
311			items,
312			pages: pages.length,
313			itemsScanned,
314		};
315	});
316	
317	function compactSession(workout: Workout): TrainingSummarySession {
318		const exercises = workout.exercises ?? [];
319		const start = parseUtcDate(workout.start_time);
320		const end = parseUtcDate(workout.end_time);
321		const duration =
322			start === undefined || end === undefined
323				? undefined
324				: DateTime.toEpochMillis(end) - DateTime.toEpochMillis(start);
325		const durationSeconds =
326			duration === undefined || duration < 0
327				? undefined
328				: Math.floor(duration / 1_000);
329		const session: MutableTrainingSummarySession = {
330			exercise_count: exercises.length,
331			set_count: exercises.reduce(
332				(total, exercise) => total + (exercise.sets?.length ?? 0),
333				0,
334			),
335		};
336		if (workout.id) session.id = workout.id;
337		if (workout.title) session.title = workout.title;
338		if (workout.start_time) session.start_time = workout.start_time;
339		if (workout.end_time) session.end_time = workout.end_time;
340		if (durationSeconds !== undefined) session.duration_seconds = durationSeconds;
341		return session;
342	}
343	
344	function workoutVolume(workout: Workout): number {
345		let total = 0;
346		for (const exercise of workout.exercises ?? []) {
347			for (const set of exercise.sets ?? []) {
348				if (
349					Predicate.isNumber(set.weight_kg) &&
350					Number.isFinite(set.weight_kg) &&
351					Predicate.isNumber(set.reps) &&
352					Number.isFinite(set.reps)
353				) {
354					total += set.weight_kg * set.reps;
355				}
356			}
357		}
358		return total;
359	}
360	
361	function compactMeasurement(
362		measurement: BodyMeasurement,
363	): TrainingSummaryMeasurement {
364		const result: MutableTrainingSummaryMeasurement = { date: measurement.date };
365		if (measurement.weight_kg != null) result.weight_kg = measurement.weight_kg;
366		if (measurement.lean_mass_kg != null) {
367			result.lean_mass_kg = measurement.lean_mass_kg;
368		}
369		if (measurement.fat_percent != null) {
370			result.fat_percent = measurement.fat_percent;
371		}
372		return result;
373	}
374	
375	function workoutListOperation(
376		operations: WorkflowsTrainingSummaryOperations,
377	): WorkoutsListOperation {
378		return "effect" in operations.workouts
379			? operations.workouts
380			: operations.workouts.list;
381	}
382	
383	function measurementListOperation(
384		operations: WorkflowsTrainingSummaryOperations,
385	): BodyMeasurementsListOperation {
386		return "effect" in operations.bodyMeasurements
387			? operations.bodyMeasurements
388			: operations.bodyMeasurements.list;
389	}
390	
391	function loadWorkoutsPage(
392		operation: WorkoutsListOperation,
393	): TrainingSummaryPageLoader<Workout> {
394		return (page, pageSize, options) => {
395			const result = operation.effect({ page, pageSize }, options);
396			return result.pipe(
397				Effect.map((response: WorkoutsListOutput) => ({
398					items: response.items,
399					pageCount: response.pageCount,
400					endOfList: response.expected404Outcome === "end_of_list",
401				})),
402				Effect.catchIf(
403					(error) => isExpectedReadEndOfList(error, "/v1/workouts", page),
404					() => Effect.succeed({ items: [], endOfList: true }),
405				),
406			);
407		};
408	}
409	
410	function loadMeasurementsPage(
411		operation: BodyMeasurementsListOperation,
412	): TrainingSummaryPageLoader<BodyMeasurement> {
413		return (page, pageSize, options) => {
414			const result = operation.effect({ page, pageSize }, options);
415			return result.pipe(
416				Effect.map((response: BodyMeasurementsListOutput) => ({
417					items: response.items,
418					pageCount: response.pageCount,
419					endOfList: response.expected404Outcome === "end_of_list",
420				})),
421				Effect.catchIf(
422					(error) =>
423						isExpectedReadEndOfList(error, "/v1/body_measurements", page),
424					() => Effect.succeed({ items: [], endOfList: true }),
425				),
426			);
427		};
428	}
429	
430	export function createWorkflowsTrainingSummaryOperation(
431		operations: WorkflowsTrainingSummaryOperations,
432		options: TrainingSummaryOperationOptions = {},
433	): WorkflowsTrainingSummaryOperation {
434		const maxWeeks = options.maxWeeks ?? MAX_TRAINING_SUMMARY_WEEKS;
435		const strictPagination = options.strictPagination ?? false;
436		return defineOperation(
437			workflowsTrainingSummaryDescriptor,
438			function* (
439				input: TrainingSummaryInput,
440				options?: HevyExecutionOptions,
441			): Effect.fn.Return<
442				TrainingSummaryResult,
443				| HevyRequestEffectError
444				| PaginationMismatchError
445				| TrainingSummaryDataError
446				| TrainingSummaryValidationError
447			> {
448				if (
449					!Number.isInteger(input.weeks) ||
450					input.weeks < MIN_TRAINING_SUMMARY_WEEKS ||
451					input.weeks > maxWeeks
452				) {
453					return yield* new TrainingSummaryValidationError({
454						weeks: input.weeks,
455						message: `Training summary weeks must be an integer from ${MIN_TRAINING_SUMMARY_WEEKS} through ${maxWeeks}`,
456					});
457				}
458	
459				const now = yield* DateTime.now;
460				const end = DateTime.startOf(now, "day");
461				const start = DateTime.subtract(end, { days: input.weeks * 7 });
462				const period = {
463					start_date: DateTime.formatIsoDateUtc(start),
464					end_date: DateTime.formatIsoDateUtc(end),
465					weeks: input.weeks,
466				};
467				const workoutLoader = loadWorkoutsPage(workoutListOperation(operations));
468				const measurementLoader = loadMeasurementsPage(
469					measurementListOperation(operations),
470				);
471				const [workoutScan, measurementScan] = yield* Effect.all(
472					[
473						scanPagesInWindow(
474							workoutLoader,
475							TRAINING_SUMMARY_PAGE_SIZE,
476							period.start_date,
477							period.end_date,
478							(workout) => workout.start_time,
479							options,
480							strictPagination,
481						),
482						scanPagesInWindow(
483							measurementLoader,
484							TRAINING_SUMMARY_PAGE_SIZE,
485							period.start_date,
486							period.end_date,
487							(measurement) => measurement.date,
488							options,
489							strictPagination,
490						),
491					],
492					{ concurrency: SCAN_CONCURRENCY },
493				);
494	
495				const sessions: TrainingSummarySession[] = [];
496				const uniqueExerciseTemplateIds = new Set<string>();
497				let totalDurationSeconds = 0;
498				let totalExerciseCount = 0;
499				let totalSetCount = 0;
500				let totalVolumeKg = 0;
501				for (const workout of workoutScan.items) {
502					const session = compactSession(workout);
503					sessions.push(session);
504					totalDurationSeconds += session.duration_seconds ?? 0;
505					totalExerciseCount += session.exercise_count;
506					totalSetCount += session.set_count;
507					totalVolumeKg += workoutVolume(workout);
508					for (const exercise of workout.exercises ?? []) {
509						if (exercise.exercise_template_id) {
510							uniqueExerciseTemplateIds.add(exercise.exercise_template_id);
511						}
512					}
513				}
514				const measurements = [...measurementScan.items].sort((left, right) =>
515					left.date.localeCompare(right.date),
516				);
517				const earliestMeasurement = measurements[0];
518				const latestMeasurement = measurements.at(-1);
519				const earliest =
520					earliestMeasurement === undefined
521						? undefined
522						: compactMeasurement(earliestMeasurement);
523				const latest =
524					latestMeasurement === undefined
525						? undefined
526						: compactMeasurement(latestMeasurement);
527				const weightChange =
528					latest?.weight_kg !== undefined && earliest?.weight_kg !== undefined
529						? latest.weight_kg - earliest.weight_kg
530						: undefined;
531				const bodyMeasurements: MutableTrainingSummaryBodyMeasurements = {
532					count: measurements.length,
533				};
534				if (latest !== undefined) bodyMeasurements.latest = latest;
535				if (earliest !== undefined) bodyMeasurements.earliest = earliest;
536				if (weightChange !== undefined) {
537					bodyMeasurements.weight_change_kg = weightChange;
538				}
539				return {
540					period,
541					workouts: {
542						count: sessions.length,
543						total_duration_seconds: totalDurationSeconds,
544						exercise_count: totalExerciseCount,
545						set_count: totalSetCount,
546						total_volume_kg: totalVolumeKg,
547						unique_exercise_template_ids: [...uniqueExerciseTemplateIds],
548						sessions,
549					},
550					body_measurements: bodyMeasurements,
551					workflow: {
552						name: "training-summary" as const,
553						pagination: {
554							workouts: workoutScan.pages,
555							body_measurements: measurementScan.pages,
556						},
557						cacheStatus: "not-used",
558						itemsScanned: workoutScan.itemsScanned + measurementScan.itemsScanned,
559					},
560				};
561			},
562		);
563	}
564	
565	export const createTrainingSummaryOperation =
566		createWorkflowsTrainingSummaryOperation;
567	
568	export const trainingSummaryDescriptor = workflowsTrainingSummaryDescriptor;

