170	export type TrainingSummaryPageLoader<T> = (
171		page: number,
172		pageSize: number,
173		options?: HevyExecutionOptions,
174	) => Effect.Effect<
175		TrainingSummaryPage<T>,
176		HevyRequestEffectError | PaginationMismatchError
177	>;
