 93	function buildRepRange(
 94		repRange: RoutineRepRangeInput | undefined,
 95	): RoutineRepRangeInput {
 96		if (!repRange) {
 97			return null;
 98		}
 99	
100		const start = repRange.start ?? undefined;
101		const end = repRange.end ?? undefined;
102		if (start === undefined && end === undefined) {
103			return null;
104		}
105	
106		return { start, end };
