109	function getFixedRepsFromRepRange(
110		repRange: RoutineRepRangeInput,
111	): number | null {
112		if (!repRange) {
113			return null;
114		}
115		const start = repRange.start ?? null;
116		const end = repRange.end ?? null;
117		if (start === null || end === null || start !== end) {
118			return null;
