134				? set.reps
135				: getFixedRepsFromRepRange(repRange);
136			const common = {
137				weight_kg: set.weight_kg ?? null,
138				reps: reps ?? null,
139				distance_meters: set.distance_meters ?? null,
140				duration_seconds: set.duration_seconds ?? null,
141				custom_metric: set.custom_metric ?? null,
142			};
143	
144			if (mode === "create") {
145				return {
146					...common,
147					type: set.type,
148					rep_range: repRange,
149				};
150			}
151			const payload: PutRoutinesRequestSet = { ...common, type: set.type };
152			if (repRange) payload.rep_range = repRange;
153			return payload;
154		});
