 84	const collectionMemberEndpoints = {
 85		"/v1/body_measurements": "/v1/body_measurements/:date",
 86		"/v1/exercise_templates": "/v1/exercise_templates/:exerciseTemplateId",
 87		"/v1/routine_folders": "/v1/routine_folders/:folderId",
 88		"/v1/routines": "/v1/routines/:routineId",
 89		"/v1/workouts": "/v1/workouts/:workoutId",
 90		"/v1/workouts/events": undefined,
 91	} as const satisfies Record<
 92		ReadCollectionEndpoint,
 93		ReadMemberEndpoint | undefined
 94	>;
 95	
 96	function errorIdentity(cause: unknown):
 97		| {
 98				readonly status?: number;
 99				readonly method: string;
100				readonly endpoint: string;
101		  }
102		| undefined {
103		if (isHevyHttpError(cause) || cause instanceof NotFoundError) {
104			return {
105				status: cause.status,
106				method: cause.method,
107				endpoint: cause.endpoint,
108			};
109		}
110		return undefined;
111	}
112	
113	/**
114	 * Classify only the documented read-side 404 cases.
115	 *
116	 * Matching is based on the tagged error's HTTP identity and the operation's
117	 * endpoint identity. It deliberately does not inspect messages or mutable
118	 * request state, so unexpected errors remain in the Effect channel.
119	 */
120	export function classifyReadError(
121		cause: unknown,
122		endpoint: ReadEndpoint,
123		page?: number,
124	): ExpectedReadError | undefined {
125		const identity = errorIdentity(cause);
126		if (
127			identity === undefined ||
128			identity.status !== 404 ||
129			identity.method.toUpperCase() !== "GET"
130		) {
131			return undefined;
132		}
133	
134		const canonicalError = canonicalEndpointIdentity(identity.endpoint);
135		const canonicalOperation = canonicalEndpointIdentity(endpoint);
136		if (page !== undefined) {
137			if (
138				page > 1 &&
139				canonicalOperation in collectionMemberEndpoints &&
140				canonicalError === canonicalOperation
141			) {
142				return "end_of_list";
143			}
144			return undefined;
145		}
146	
147		if (
148			canonicalOperation in collectionMemberEndpoints &&
149			canonicalError ===
150				collectionMemberEndpoints[canonicalOperation as ReadCollectionEndpoint]
151		) {
152			return "not_found";
153		}
154		if (canonicalOperation === canonicalError) {
155			const memberEndpoint = canonicalOperation as ReadMemberEndpoint;
156			if (
157				memberEndpoint === "/v1/body_measurements/:date" ||
158				memberEndpoint === "/v1/exercise_templates/:exerciseTemplateId" ||
159				memberEndpoint === "/v1/routine_folders/:folderId" ||
160				memberEndpoint === "/v1/routines/:routineId" ||
161				memberEndpoint === "/v1/workouts/:workoutId"
162			) {
163				return "not_found";
164			}
165		}
166		return undefined;
167	}
168	
169	export function isExpectedReadNotFound(
170		cause: unknown,
171		endpoint: ReadEndpoint,
172	): boolean {
173		return classifyReadError(cause, endpoint) === "not_found";
174	}
175	
176	export function isExpectedReadEndOfList(
177		cause: unknown,
178		endpoint: ReadCollectionEndpoint,
179		page: number,
180	): boolean {
181		return page > 1 && classifyReadError(cause, endpoint, page) === "end_of_list";
182	}
