184	/**
185	 * Detect the Hevy API's empty-object responses, which signal "no entity"
186	 * where a 404 would be expected. Shared so the shape check cannot drift
187	 * between operation modules.
188	 */
189	export function isEmptyResponse<T extends object>(
190		response: T | null | undefined,
191	): response is T & Record<never, never> {
192		return (
193			response !== null &&
194			response !== undefined &&
195			Object.keys(response).length === 0
196		);
197	}
198	
199	/**
200	 * Recover a documented read-side 404 as a successful absence value.
201	 * Pipeable so get-style operations keep one outcome-mapping shape.
202	 */
203	export function withExpectedNotFound<A, E, Absent>(
204		endpoint: ReadEndpoint,
205		absent: Absent,
206	): (effect: Effect.Effect<A, E>) => Effect.Effect<A | Absent, E> {
207		return (effect) =>
208			effect.pipe(
209				Effect.catchIf(
210					(cause) => isExpectedReadNotFound(cause, endpoint),
211					() => Effect.succeed(absent),
212				),
213			);
214	}
215	
216	/**
217	 * Recover a documented later-page 404 as a successful end-of-list value.
218	 * Pipeable so list-style operations keep one outcome-mapping shape.
219	 */
220	export function withExpectedEndOfList<A, E, Absent>(
221		endpoint: ReadCollectionEndpoint,
222		page: number,
223		absent: Absent,
224	): (effect: Effect.Effect<A, E>) => Effect.Effect<A | Absent, E> {
225		return (effect) =>
226			effect.pipe(
227				Effect.catchIf(
228					(cause) => isExpectedReadEndOfList(cause, endpoint, page),
229					() => Effect.succeed(absent),
230				),
231			);
232	}
233	
234	/**
235	 * Fail when the API echoes a different page than requested. Compose with
236	 * `Effect.tap` ahead of response projection so list operations share one
237	 * page-echo policy.
238	 */
239	export function assertPageEcho(
240		response: { readonly page?: number | undefined } | null | undefined,
241		requestedPage: number,
242		collection: string,
243	): Effect.Effect<void, PaginationMismatchError> {
244		if (response?.page !== undefined && response.page !== requestedPage) {
245			return Effect.fail(
246				new PaginationMismatchError({
247					requested: requestedPage,
248					received: response.page,
249					collection,
250					message: `Page mismatch for ${collection}: requested page ${requestedPage} but received page ${response.page}`,
251				}),
252			);
253		}
254		return Effect.void;
255	}
256	
257	/**
258	 * Decide whether pagination continues: the page was non-empty and the API
259	 * reports more pages. Shared so every collection applies the same policy.
260	 */
261	export function hasNextPage(
262		pageCount: number | undefined,
263		page: number,
264		itemCount: number,
265	): boolean {
266		return (
267			itemCount > 0 &&
268			Predicate.isNumber(pageCount) &&
269			Number.isSafeInteger(pageCount) &&
270			pageCount > page
271		);
272	}
273	import { Effect } from "effect";
274	
275	export interface DefinedOperation<
276		Descriptor,
277		Args extends readonly unknown[],
278		Result,
279		Error,
280	> {
281		readonly descriptor: Descriptor;
282		readonly effect: (...args: Args) => Effect.Effect<Result, Error>;
283		execute(...args: Args): Promise<Result>;
284	}
285	
286	/**
287	 * Build one operation triple from a descriptor and a generator body.
288	 *
289	 * The tracing span derives from the descriptor (`operations.<id>`), so span
290	 * names cannot drift from operation identity. `execute` runs the same effect
291	 * value instead of closing over the partially built operation object. The
292	 * yielded-effect constraint rejects `R` at compile time: only `R = never`
293	 * bodies satisfy it, which is what keeps the `Effect.runPromise` edge total.
294	 * `E` resolves as the union of every yielded failure, so bodies that recover
295	 * typed errors keep their full channel.
296	 */
297	export function defineOperation<
298		const Descriptor extends { readonly id: string },
299		const Args extends readonly unknown[],
300		Yielded extends Effect.Effect<unknown, unknown, never>,
301		Result,
302	>(
303		descriptor: Descriptor,
304		body: (...args: Args) => Generator<Yielded, Result, never>,
305	): DefinedOperation<Descriptor, Args, Result, Effect.Error<Yielded>> {
306		const traced = Effect.fn(`operations.${descriptor.id}`)(body);
307		// Discharge Effect.fn's deferred conditional inference, which cannot
308		// resolve inside a generic boundary. The Yielded constraint already proves
309		// R = never, and Effect.Error<Yielded> is exactly the union Effect.fn
310		// computes — identical at every call site once Yielded is concrete.
311		const effect = traced as (
312			...args: Args
313		) => Effect.Effect<Result, Effect.Error<Yielded>>;
314		return {
315			descriptor,
316			effect,
317			execute(...args: Args) {
318				return Effect.runPromise(effect(...args));
319			},
320		};
321	}

