297		// channel. Anything else (e.g. a TypeError from a programming bug) is a
298		// defect and must stay loud instead of being mislabeled a payload error.
299		return Effect.suspend(() => {
300			try {
301				return Effect.succeed(
302					buildWorkoutUpdatePayload(current, patch, replacementExercises),
303				);
304			} catch (cause) {
305				if (
306					cause instanceof WorkoutPrivacyError ||
307					cause instanceof WorkoutPayloadError
308				) {
309					return Effect.fail(cause);
310				}
311				return Effect.die(cause);
312			}
313		});
314	}
315	
316	export function createWorkoutsCreateOperation(
317		adapter: WorkoutsCreateAdapter,
318	): WorkoutsCreateOperation {
319		return defineOperation(
320			workoutsCreateDescriptor,
321			function* (input: WorkoutsCreateInput, options?: HevyExecutionOptions) {
322				const request = adapter.createWorkout(
323					{ workout: input.workout },
324					options,
325				);
326				const response = yield* request;
327				return isEmptyResponse(response) ? undefined : response;
328			},
329		);
330	}
331	
332	export function createWorkoutsEventsOperation(
333		adapter: WorkoutsEventsAdapter,
334	): WorkoutsEventsOperation {
335		return defineOperation(
336			workoutsEventsDescriptor,
337			function* (input: WorkoutsEventsInput, options?: HevyExecutionOptions) {
338				const params =
339					input.since === undefined
340						? { page: input.page, pageSize: input.pageSize }
341						: {
342								page: input.page,
343								pageSize: input.pageSize,
344								since: input.since,
345							};
346				const request = adapter.getWorkoutEvents(params, options);
347				return yield* request.pipe(
348					Effect.tap((response) =>
349						assertPageEcho(response, input.page, "workoutEvents"),
350					),
351					Effect.map((response: GetV1WorkoutsEvents200) => ({
352						events: response?.events ?? [],
353						page: response?.page ?? input.page,
354						pageCount: response?.page_count,
355						since: input.since,
356					})),
357					withExpectedEndOfList("/v1/workouts/events", input.page, {
358						events: [],
359						page: input.page,
360						pageCount: undefined,
361						since: input.since,
362						expected404Outcome: "end_of_list" as const,
363					}),
364				);
365			},
366		);
367	}
368	
369	export function createWorkoutsUpdateOperation(
370		adapter: WorkoutsUpdateAdapter,
371	): WorkoutsUpdateOperation {
372		return defineOperation(
373			workoutsUpdateDescriptor,
374			function* (input: WorkoutsUpdateInput, options?: HevyExecutionOptions) {
375				const patch = "patch" in input ? input.patch : input.workout;
376				const replacementExercises = isWorkoutReplacementPatch(patch)
377					? patch.exercises
378					: undefined;
379				const current = yield* adapter.getWorkout(input.workoutId, options);
380				const payload = yield* workoutPayloadEffect(
381					current,
382					patch,
383					replacementExercises,
384				);
385				const updateRequest = adapter.updateWorkout(
386					input.workoutId,
387					{ workout: payload },
388					options,
389				);
390				const response = yield* updateRequest;
391				return isEmptyResponse(response) ? undefined : response;
392			},
393		);
394	}
395	
396	export function createWorkoutsReplaceExercisesOperation(
397		adapter: WorkoutsReplaceExercisesAdapter,
398	): WorkoutsReplaceExercisesOperation {
399		return defineOperation(
400			workoutsReplaceExercisesDescriptor,
401			function* (
402				input: WorkoutsReplaceExercisesInput,
403				options?: HevyExecutionOptions,
404			) {
405				const getRequest = adapter.getWorkout(input.workoutId, options);
406				const current = yield* getRequest;
407				const payload = yield* workoutPayloadEffect(
408					current,
409					{ is_private: input.is_private },
410					input.exercises,
411				);
412				const updateRequest = adapter.updateWorkout(
413					input.workoutId,
414					{ workout: payload },
415					options,
416				);
417				const response = yield* updateRequest;
418				return isEmptyResponse(response) ? undefined : response;
